set -eu
base=/root/sugarscape/dynasoar-cuda91-native-002
mkdir -p "$base/diagnostic"
cd "$base/diagnostic"
trap 'run_exit=$?; trap - EXIT; printf "{\"exit_code\": %s}\n" "$run_exit" > terminal.json; tar -C "$base" -czf "$base/complete-evidence.tar.gz" diagnostic; sha256sum "$base/complete-evidence.tar.gz"; exit "$run_exit"' EXIT
printf '%s'  | base64 -d > qualify_historical.py
printf '%s\n' '/usr/local/cuda-9.1/nvvm/lib64' > /root/sugarscape/dynasoar-cuda91-003/image/rootfs/etc/ld.so.conf.d/sugarscape-cuda91-nvvm.conf
chroot /root/sugarscape/dynasoar-cuda91-003/image/rootfs /sbin/ldconfig
chroot /root/sugarscape/dynasoar-cuda91-003/image/rootfs /sbin/ldconfig -p > loader-cache.txt
sha256sum /root/sugarscape/dynasoar-cuda91-003/image/rootfs/usr/local/cuda-9.1/nvvm/lib64/libnvvm.so.3.2.0 > nvvm-sha256.txt
python3 qualify_historical.py /root/sugarscape/dynasoar-cuda91-003/image/rootfs /root/sugarscape/dynasoar-qualification-portable-004/qualification/native/artifact.zip "$base/diagnostic/native" --build-directory /work/dynasoar-cuda91-native-002 > native.log 2>&1
